mapper.select:
SELECT m.* FROM conversation_message m WHERE m.session_id = #{sessionId}
    AND NOT EXISTS(SELECT 1 FROM agent_run_submission s JOIN agent_run_state r ON r.run_id=s.run_id
        WHERE s.run_id=m.run_id AND r.status IN ('CREATED','RUNNING','WAITING_APPROVAL','RESUMING'))
ORDER BY m.id DESC LIMIT #{pageable.pageSize} OFFSET #{pageable.offset}

SELECT * FROM conversation_message WHERE session_id=#{sessionId}
AND id < #{beforeId}
ORDER BY id DESC LIMIT #{limit}
